   376	  idx = ndpi_proto_id - ndpi_str->num_internal_protocols;
   377	
   378	  if(idx >= ndpi_str->ndpi_to_user_proto_id_num_allocated) {
   379	    int new_num;
   380	    u_int16_t *new_ptr;
   381	
   382	    new_num = ndpi_max(64, ndpi_str->ndpi_to_user_proto_id_num_allocated * 2);
   383	    new_ptr = ndpi_realloc(ndpi_str->ndpi_to_user_proto_id,
   384	                           ndpi_str->ndpi_to_user_proto_id_num_allocated * sizeof(u_int16_t),
   385	                           new_num * sizeof(u_int16_t));
   386	    if(!new_ptr) {
   387	      NDPI_LOG_DBG(ndpi_str, "Realloc error\n");
   388	      return;
   389	    }
   390	    ndpi_str->ndpi_to_user_proto_id = new_ptr;
   391	    ndpi_str->ndpi_to_user_proto_id_num_allocated = new_num;
   392	  }
   393	
   394	  ndpi_str->ndpi_to_user_proto_id[idx] = user_proto_id;
